script.setup:
// 9,000 points swirl in five swarms; d3-hexbin bins them into hexagons every frame and the
// scene draws one instanced hexagon per bin, colored (and optionally sized) by its count.
const mod = await ctx.utils.import("https://esm.sh/d3-hexbin@0.2.2");
const { hexbin } = mod.hexbin ? mod : (mod.default ?? mod);
const N = 9000, SWARMS = 5;
const pts = Array.from({ length: N }, (_, i) => {
  // Gaussian-ish spread around the swarm center; inner points orbit faster.
  const r = Math.sqrt(-2 * Math.log(Math.random() + 1e-9)) * 70, a = Math.random() * Math.PI * 2;
  return { swarm: i % SWARMS, r, a, spin: (0.4 + Math.random() * 0.4) * (i % 2 ? 1 : 1) * 60 / (r + 30), x: 0, y: 0 };
});
const gl = ctx.gl;
// Unit hexagon (pointy top, like d3-hexbin's) as 6 triangles.
const hex = [];
for (let k = 0; k < 6; k++) {
  const a0 = Math.PI / 2 + k * Math.PI / 3, a1 = a0 + Math.PI / 3;
  hex.push(0, 0, Math.cos(a0), Math.sin(a0), Math.cos(a1), Math.sin(a1));
}
const vao = gl.createVertexArray();
gl.bindVertexArray(vao);
const shape = gl.createBuffer();
gl.bindBuffer(gl.ARRAY_BUFFER, shape); gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(hex), gl.STATIC_DRAW);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
const inst = gl.createBuffer();
gl.bindBuffer(gl.ARRAY_BUFFER, inst);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 3, gl.FLOAT, false, 0, 0); gl.vertexAttribDivisor(1, 1);
gl.bindVertexArray(null);
const dotsVao = gl.createVertexArray(), dots = gl.createBuffer();
gl.bindVertexArray(dotsVao); gl.bindBuffer(gl.ARRAY_BUFFER, dots);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
gl.bindVertexArray(null);
const hexProgram = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_corner; layout(location=1) in vec3 a_bin;
uniform vec2 u_view; uniform float u_radius; uniform float u_max; uniform bool u_sized; uniform float u_gap;
out float v_t; out float v_edge;
void main(){
  v_t = clamp(a_bin.z / u_max, 0.0, 1.0);
  float size = u_sized ? mix(0.3, 1.0, sqrt(v_t)) : 1.0;
  v_edge = length(a_corner);
  vec2 p = a_bin.xy + a_corner * u_radius * (1.0 - u_gap) * size;
  gl_Position = vec4(p / u_view * 2.0 - 1.0, 0.0, 1.0);
}`, `#version 300 es
precision highp float; in float v_t; in float v_edge; out vec4 outColor;
uniform vec3 u_low; uniform vec3 u_mid; uniform vec3 u_high;
void main(){
  vec3 c = v_t < 0.5 ? mix(u_low, u_mid, v_t * 2.0) : mix(u_mid, u_high, v_t * 2.0 - 1.0);
  outColor = vec4(c * (0.85 + 0.25 * (1.0 - v_edge)), 1.0);
}`);
const dotProgram = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_position; uniform vec2 u_view; uniform float u_px;
void main(){ gl_Position = vec4(a_position / u_view * 2.0 - 1.0, 0.0, 1.0); gl_PointSize = u_px; }`, `#version 300 es
precision highp float; out vec4 outColor; uniform float u_dots;
void main(){ outColor = vec4(vec3(1.0) * u_dots, 1.0); }`);
Object.assign(ctx.state, { hexbin, N, SWARMS, pts, vao, inst, dotsVao, dots, hexProgram, dotProgram, xy: new Float32Array(N * 2), moved: false });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const H = 1000, W = H * w / h, t = ctx.time * u.u_speed;
s.moved ||= ctx.mouse[0] !== 0.5 || ctx.mouse[1] !== 0.5;
// Swarm centers wander on Lissajous curves; the first follows the pointer once it moves.
const centers = Array.from({ length: s.SWARMS }, (_, k) => [
  W / 2 + Math.sin(t * (0.21 + k * 0.05) + k * 1.9) * W * 0.33,
  H / 2 + Math.sin(t * (0.17 + k * 0.04) + k * 0.7) * H * 0.3,
]);
if (s.moved) { s.pointer ??= centers[0]; s.pointer = [s.pointer[0] + (ctx.mouse[0] * W - s.pointer[0]) * 0.08, s.pointer[1] + ((1 - ctx.mouse[1]) * H - s.pointer[1]) * 0.08]; centers[0] = s.pointer; }
const spread = u.u_spread;
s.pts.forEach((p, i) => {
  p.a += p.spin * ctx.dt * u.u_speed;
  const c = centers[p.swarm], r = p.r * spread * (1 + 0.25 * Math.sin(t * 0.7 + p.swarm));
  p.x = c[0] + Math.cos(p.a) * r * 1.2;
  p.y = c[1] + Math.sin(p.a) * r;
  s.xy[i * 2] = p.x; s.xy[i * 2 + 1] = p.y;
});
const radius = u.u_radius;
const bins = s.hexbin().radius(radius).extent([[0, 0], [W, H]]).x((p) => p.x).y((p) => p.y)(s.pts);
const inst = new Float32Array(bins.length * 3);
let max = 1;
bins.forEach((b, i) => { inst.set([b.x, b.y, b.length], i * 3); max = Math.max(max, b.length); });
s.max = (s.max ?? max) + (max - (s.max ?? max)) * 0.1;
gl.clearColor(0.03, 0.03, 0.045, 1); gl.clear(gl.COLOR_BUFFER_BIT);
gl.useProgram(s.hexProgram);
ctx.utils.setUniforms(s.hexProgram, { u_view: [W, H], u_radius: radius, u_max: s.max, u_sized: u.u_sized, u_gap: 0.08, u_low: u.u_low, u_mid: u.u_mid, u_high: u.u_high });
gl.bindVertexArray(s.vao); gl.bindBuffer(gl.ARRAY_BUFFER, s.inst);
gl.bufferData(gl.ARRAY_BUFFER, inst, gl.DYNAMIC_DRAW);
gl.drawArraysInstanced(gl.TRIANGLES, 0, 18, bins.length);
if (u.u_dots > 0) {
  gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
  gl.useProgram(s.dotProgram);
  ctx.utils.setUniforms(s.dotProgram, { u_view: [W, H], u_px: Math.max(1, h / 700), u_dots: u.u_dots });
  gl.bindVertexArray(s.dotsVao); gl.bindBuffer(gl.ARRAY_BUFFER, s.dots);
  gl.bufferData(gl.ARRAY_BUFFER, s.xy, gl.DYNAMIC_DRAW);
  gl.drawArrays(gl.POINTS, 0, s.N);
  gl.disable(gl.BLEND);
}
gl.bindVertexArray(null);
ctx.publish("bins", bins.length);
ctx.publish("fullest bin", max);
